// ══════════════════════════════════════════════════════════════
// BEFORE: a single smelly function
// Smells: opaque names, magic numbers, does too much, long method
// ══════════════════════════════════════════════════════════════
function process(u, t) {
  // check if valid
  if (u.age >= 18 && !u.banned && t === 'premium') {
    let x = u.balance * 0.9;   // 10% discount — magic number
    if (x > 1000) x = 1000;    // cap — magic number
    return x;
  }
  return u.balance;
}
console.log(process({ age: 25, banned: false, balance: 1200 }, 'premium')); // 1000


// ══════════════════════════════════════════════════════════════
// AFTER: four named refactorings applied
// 1. Replace Magic Number with Symbolic Constant
// 2. Rename (process→calcFinalBalance, u→user, t→tierType, x→discountAmount)
// 3. Extract Variable (isEligibleForDiscount)
// 4. Extract Function (isEligibleForDiscount, calcDiscount)
// ══════════════════════════════════════════════════════════════
const PREMIUM_DISCOUNT_RATE = 0.10;  // 10%
const MAX_DISCOUNT_AMOUNT   = 1000;

function isEligibleForDiscount(user, tierType) {
  return user.age >= 18 && !user.banned && tierType === 'premium';
}

function calcDiscount(balance) {
  const rawDiscount = balance * PREMIUM_DISCOUNT_RATE;
  return Math.min(rawDiscount, MAX_DISCOUNT_AMOUNT);
}

function calcFinalBalance(user, tierType) {
  if (!isEligibleForDiscount(user, tierType)) return user.balance;
  return user.balance - calcDiscount(user.balance);
}

// same observable results — tests would still pass
console.log(calcFinalBalance({ age: 25, banned: false, balance: 1200 }, 'premium')); // 1000
console.log(calcFinalBalance({ age: 15, banned: false, balance: 1200 }, 'premium')); // 1200
console.log(calcFinalBalance({ age: 25, banned: true,  balance: 1200 }, 'premium')); // 1200

// ══════════════════════════════════════════════════════════════
// BEFORE: chained if/else on type — adding 'overnight' requires
// editing this function AND every similar function in the codebase
// ══════════════════════════════════════════════════════════════
function getShippingCost(type) {
  if (type === 'express')  return 25;
  if (type === 'standard') return 10;
  if (type === 'free')     return 0;
  return 15; // default
}
function getShippingLabel(type) {
  if (type === 'express')  return 'Express (1 day)';
  if (type === 'standard') return 'Standard (3-5 days)';
  if (type === 'free')     return 'Free Shipping';
  return 'Unknown';
}
// Adding 'overnight' requires editing BOTH functions — easy to forget one


// ══════════════════════════════════════════════════════════════
// AFTER: Replace Conditional with Strategy map
// Adding 'overnight' = one new entry, zero function edits
// ══════════════════════════════════════════════════════════════
const SHIPPING_OPTIONS = {
  express:  { cost: 25,  label: 'Express (1 day)' },
  standard: { cost: 10,  label: 'Standard (3-5 days)' },
  free:     { cost: 0,   label: 'Free Shipping' },
  overnight:{ cost: 45,  label: 'Overnight (next day)' }, // new type: one line
};
const DEFAULT_SHIPPING = { cost: 15, label: 'Unknown' };

const getShipping = (type) => SHIPPING_OPTIONS[type] ?? DEFAULT_SHIPPING;

console.log(getShipping('express').cost);     // 25
console.log(getShipping('overnight').label);  // 'Overnight (next day)'
console.log(getShipping('drone').cost);       // 15 (default)

// Bonus: you can now iterate over all valid types:
const allTypes = Object.keys(SHIPPING_OPTIONS);
console.log(allTypes); // ['express', 'standard', 'free', 'overnight']

// ══════════════════════════════════════════════════════════════
// Introduce Parameter Object
// ══════════════════════════════════════════════════════════════

// BEFORE — 5 positional args, easy to swap two accidentally
function createOrder(customerId, productId, quantity, discountCode, shippingType) {
  console.log(`Order: cust=${customerId} prod=${productId} qty=${quantity}`);
}
createOrder(1, 42, 2, 'SAVE10', 'express'); // which arg is which?

// AFTER — destructured parameter object, call-site is self-documenting
function createOrderV2({ customerId, productId, quantity, discountCode, shippingType }) {
  console.log(`Order: cust=${customerId} prod=${productId} qty=${quantity}`);
}
createOrderV2({ customerId: 1, productId: 42, quantity: 2, discountCode: 'SAVE10', shippingType: 'express' });
// No ambiguity, and adding a 6th option (e.g. giftWrap: true) is zero-friction


// ══════════════════════════════════════════════════════════════
// Extract Variable (Explaining Variable)
// ══════════════════════════════════════════════════════════════

// BEFORE — reader must decode the boolean expression every time
if (user.subscriptionEnd > Date.now() && !user.cancelled && user.plan !== 'free') {
  grantAccess(user);
}

// AFTER — the condition has a name that explains business intent
const isActivePayingSubscriber =
  user.subscriptionEnd > Date.now() && !user.cancelled && user.plan !== 'free';
if (isActivePayingSubscriber) {
  grantAccess(user); // now reads like a sentence
}


// ══════════════════════════════════════════════════════════════
// Encapsulate Field — using private class field (#)
// ══════════════════════════════════════════════════════════════

// BEFORE — any caller can silently corrupt the balance
class Account {
  constructor(initialBalance) { this.balance = initialBalance; }
}
const acct = new Account(500);
acct.balance = -9999; // no error, silent bad state
console.log(acct.balance); // -9999

// AFTER — validation in one place, enforced by the language
class AccountSafe {
  #balance;
  constructor(initialBalance) {
    if (initialBalance < 0) throw new RangeError('Initial balance cannot be negative');
    this.#balance = initialBalance;
  }
  get balance() { return this.#balance; }
  set balance(amount) {
    if (typeof amount !== 'number' || amount < 0)
      throw new RangeError(`Invalid balance: ${amount}`);
    this.#balance = amount;
  }
  deposit(amount) { this.balance = this.#balance + amount; }
  withdraw(amount) { this.balance = this.#balance - amount; } // reuses setter validation
}
const safe = new AccountSafe(500);
try { safe.balance = -9999; } catch (e) { console.log(e.message); } // Invalid balance: -9999
console.log(safe.balance); // 500 — unchanged, protected

